addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)&&state==='playing')e.preventDefault();if(e.key==='Escape'){if(state==='playing'&&!paused){e.preventDefault();pause();}return;}if($('modal').open)return;keys.add(e.key.toLowerCase());if(e.code==='Space'&&!e.repeat)power();});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
